// ---------- 终端 IPC（node-pty）----------
// Windows：GUI 进程继承的是「登录那一刻」的 PATH，登录后才装的 CLI（如 cursor-agent）当前会话找不到。
// mac 走 login shell（下方 -l）解决；Windows 的 powershell 无此机制，开终端时从注册表取一次最新 PATH 覆盖。
// 首次开终端才查注册表，结果缓存，避免每次开终端都拉起一个 powershell。
let winPathCache = null;
function freshWindowsPath() {
  if (process.platform !== 'win32') return null;
  if (winPathCache !== null) return winPathCache;
  try {
    const out = require('child_process').execFileSync('powershell.exe',
      ['-NoProfile', '-Command', "[Environment]::GetEnvironmentVariable('Path','Machine')+';'+[Environment]::GetEnvironmentVariable('Path','User')"],
      { encoding: 'utf8', timeout: 5000 });
    winPathCache = (out || '').trim();
  } catch { winPathCache = ''; }
  return winPathCache;
}
ipcMain.handle('pty:spawn', (e, { id, cwd, cols, rows }) => {

const env = { ...process.env, TERM: 'xterm-256color', FANBOX: '1' };
if (!/UTF-8/i.test(env.LC_ALL || env.LC_CTYPE || env.LANG || '')) env.LANG = 'zh_CN.UTF-8';
const winPath = freshWindowsPath();
if (winPath) env.Path = winPath; // Windows 用最新 PATH，找得到登录后才装的 CLI

// ---------- Agent 对话窗后端：统一 SSE 接口，按 backend 路由到 cursor / api / codex ----------
// 前端一个聊天 UI，这里做适配层。cursor/codex 用各自 CLI 的无头流式模式，api 直连 OpenAI 兼容接口。
function sseInit(res) {
  res.writeHead(200, {
    'Content-Type': 'text/event-stream; charset=utf-8',
    'Cache-Control': 'no-cache, no-transform',
    Connection: 'keep-alive',
    'X-Accel-Buffering': 'no',
  });
}
function sseSend(res, event, data) {
  try { res.write(`event: ${event}\ndata: ${JSON.stringify(data)}\n\n`); } catch { /* 连接已断 */ }
}
function pickChatCfg(cfg) {
  return {
    chatApiBaseUrl: cfg.chatApiBaseUrl || '',
    chatApiModel: cfg.chatApiModel || '',
    chatBackend: cfg.chatBackend || 'cursor',
    hasApiKey: !!cfg.chatApiKey,
  };
}

// 定位 cursor-agent：Windows 直接用 versions 下最新版本的 index.js + 自带 node.exe，
// 绕过启动器的「版本目录命名 / 缺 node.exe / PATH 不刷新」三个坑；失败再退回 PATH 上的命令。
function resolveCursorAgent() {
  if (PLATFORM === 'win32') {
    try {
      const base = path.join(process.env.LOCALAPPDATA || path.join(HOME, 'AppData', 'Local'), 'cursor-agent', 'versions');
      const dirs = fs.readdirSync(base, { withFileTypes: true }).filter((d) => d.isDirectory()).map((d) => d.name).sort();
      for (const name of dirs.reverse()) { // 版本名以日期打头，倒序≈从新到旧
        const node = path.join(base, name, 'node.exe');
        const index = path.join(base, name, 'index.js');
        if (fs.existsSync(node) && fs.existsSync(index)) return { file: node, pre: [index], shell: false };
      }
    } catch { /* 落到 PATH */ }
    return { file: 'cursor-agent.cmd', pre: [], shell: true };
  }
  return { file: 'cursor-agent', pre: [], shell: false };
}

function chatCursor(res, body) {
  const cwd = (body.cwd && fs.existsSync(body.cwd)) ? body.cwd : HOME;
  const { file, pre, shell } = resolveCursorAgent();
  const args = [...pre, '-p', String(body.message || ''),
    '--output-format', 'stream-json', '--stream-partial-output', '--force', '--workspace', cwd];
  if (body.sessionId) args.push('--resume', String(body.sessionId));
  if (body.mode === 'plan' || body.mode === 'ask') args.push('--mode', body.mode);
  let child;
  try { child = spawn(file, args, { cwd, shell, env: process.env }); }
  catch (e) { sseSend(res, 'error', { message: 'cursor-agent 启动失败：' + e.message }); return res.end(); }
  let buf = '';
  let sentSession = body.sessionId || '';
  let gotAny = false;
  child.stdout.on('data', (chunk) => {
    buf += chunk.toString('utf8');
    let nl;
    while ((nl = buf.indexOf('\n')) >= 0) {
      const line = buf.slice(0, nl).trim();
      buf = buf.slice(nl + 1);
      if (!line) continue;
      let ev; try { ev = JSON.parse(line); } catch { continue; }
      if (!ev || !ev.type) continue;
      if (ev.session_id && ev.session_id !== sentSession) { sentSession = ev.session_id; sseSend(res, 'session', { id: ev.session_id }); }
      if (ev.type === 'assistant' && ev.message && Array.isArray(ev.message.content) && ev.timestamp_ms) {
        for (const c of ev.message.content) { if (c.type === 'text' && c.text) { gotAny = true; sseSend(res, 'delta', { text: c.text }); } }
      } else if (ev.type === 'result') {
        sseSend(res, 'result', { text: ev.result || '', usage: ev.usage || null, isError: !!ev.is_error });
      }
    }
  });
  let errTail = '';
  child.stderr.on('data', (c) => { errTail = (errTail + c.toString('utf8')).slice(-500); });
  child.on('error', (e) => { sseSend(res, 'error', { message: e.message }); res.end(); });
  child.on('close', (code) => {
    if (!gotAny && code) sseSend(res, 'error', { message: `cursor-agent 退出码 ${code}${errTail ? '：' + errTail.trim() : '（可能未登录，终端里跑一次 cursor-agent login）'}` });
    sseSend(res, 'done', {});
    res.end();
  });
  res.on('close', () => { try { child.kill(); } catch { /* */ } });
}

async function chatApi(res, body) {
  const cfg = await readConfig();
  const baseUrl = (cfg.chatApiBaseUrl || '').replace(/\/+$/, '');
  const key = cfg.chatApiKey || '';
  const model = cfg.chatApiModel || '';
  if (!baseUrl || !key || !model) { sseSend(res, 'error', { message: '请先在对话窗设置里填写 API 地址 / Key / 模型' }); return res.end(); }
  const messages = (Array.isArray(body.history) ? body.history : []).filter((m) => m && m.role && typeof m.content === 'string');
  messages.push({ role: 'user', content: String(body.message || '') });
  try {
    const r = await fetch(`${baseUrl}/chat/completions`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${key}` },
      body: JSON.stringify({ model, messages, stream: true }),
    });
    if (!r.ok || !r.body) { const t = await r.text().catch(() => ''); sseSend(res, 'error', { message: `API ${r.status}: ${t.slice(0, 300)}` }); return res.end(); }
    const reader = r.body.getReader();
    const dec = new TextDecoder();
    let buf = '';
    for (;;) {
      const { done, value } = await reader.read();
      if (done) break;
      buf += dec.decode(value, { stream: true });
      let nl;
      while ((nl = buf.indexOf('\n')) >= 0) {
        let line = buf.slice(0, nl).trim();
        buf = buf.slice(nl + 1);
        if (!line.startsWith('data:')) continue;
        line = line.slice(5).trim();
        if (line === '[DONE]') continue;
        let j; try { j = JSON.parse(line); } catch { continue; }
        const d = j.choices && j.choices[0] && j.choices[0].delta && j.choices[0].delta.content;
        if (d) sseSend(res, 'delta', { text: d });
      }
    }
    sseSend(res, 'done', {});
    res.end();
  } catch (e) { sseSend(res, 'error', { message: 'API 调用失败：' + e.message }); res.end(); }
}

