.sk-mark { padding: 20px 10px 6px; font-family: var(--font-display); font-size: 12.5px; color: var(--text-faint); letter-spacing: 0.06em; border-bottom: 1px solid var(--rule); font-style: italic; }

/* ---------- AI 对话窗 ---------- */
.chat-overlay { position: fixed; inset: 0; background: rgba(0,0,0,0.5); backdrop-filter: blur(4px); display: flex; align-items: center; justify-content: center; z-index: 420; }
.chat-overlay.hidden { display: none; }
.chat-panel { width: min(900px, 92vw); height: min(82vh, 920px); background: var(--panel); border: 1px solid var(--border); border-radius: var(--radius); box-shadow: var(--shadow); display: flex; flex-direction: column; overflow: hidden; }
.chat-head { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 10px 12px; border-bottom: 1px solid var(--border); background: var(--bg-2); }
.chat-head-left { display: flex; align-items: center; gap: 10px; min-width: 0; }
.chat-title { font-weight: 600; font-size: 14px; color: var(--text); }
.chat-select { background: var(--bg-3); color: var(--text); border: 1px solid var(--border); border-radius: 6px; padding: 4px 8px; font-size: 12.5px; cursor: pointer; }
.chat-status { font-size: 11.5px; color: var(--text-dim); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.chat-head-right { display: flex; align-items: center; gap: 6px; }
.chat-iconbtn { background: transparent; border: 1px solid transparent; color: var(--text-dim); border-radius: 6px; padding: 4px 8px; font-size: 12.5px; cursor: pointer; transition: 0.12s; }
.chat-iconbtn:hover { background: var(--bg-3); color: var(--text); }
.chat-settings { padding: 12px; border-bottom: 1px solid var(--border); background: var(--bg-2); display: flex; flex-direction: column; gap: 8px; }
.chat-settings.hidden { display: none; }
.chat-set-row { display: flex; align-items: center; gap: 10px; }
.chat-set-row label { width: 64px; font-size: 12px; color: var(--text-dim); flex: none; }
.chat-set-row input { flex: 1; background: var(--bg-3); color: var(--text); border: 1px solid var(--border); border-radius: 6px; padding: 6px 9px; font-size: 12.5px; font-family: var(--font-mono); }
.chat-set-actions { display: flex; align-items: center; justify-content: space-between; gap: 10px; }
.chat-set-hint { font-size: 11px; color: var(--text-faint); }
.chat-save-btn, .chat-send-btn { background: var(--accent); color: var(--accent-ink); border: none; border-radius: 6px; padding: 7px 16px; font-size: 12.5px; font-weight: 600; cursor: pointer; }
.chat-save-btn:hover, .chat-send-btn:hover { filter: brightness(1.05); }
.chat-send-btn:disabled { opacity: 0.5; cursor: default; }
.chat-messages { flex: 1; overflow-y: auto; padding: 18px; display: flex; flex-direction: column; gap: 14px; }
.chat-empty { margin: auto; text-align: center; color: var(--text-faint); font-size: 13px; line-height: 1.9; }
.chat-msg { display: flex; flex-direction: column; max-width: 84%; }
.chat-msg.user { align-self: flex-end; align-items: flex-end; }
.chat-msg.assistant { align-self: flex-start; align-items: flex-start; }
.chat-bubble { padding: 10px 14px; border-radius: 12px; font-size: 13.5px; line-height: 1.65; word-break: break-word; overflow-wrap: anywhere; }
.chat-msg.user .chat-bubble { background: var(--accent); color: var(--accent-ink); border-bottom-right-radius: 4px; }
.chat-msg.assistant .chat-bubble { background: var(--bg-3); color: var(--text); border-bottom-left-radius: 4px; }
.chat-bubble p { margin: 0 0 8px; } .chat-bubble p:last-child { margin-bottom: 0; }
.chat-bubble pre { background: var(--bg); border: 1px solid var(--border); border-radius: 6px; padding: 10px; overflow-x: auto; font-family: var(--font-mono); font-size: 12px; }
.chat-bubble code { font-family: var(--font-mono); font-size: 12px; }
.chat-bubble :not(pre) > code { background: var(--bg); padding: 1px 5px; border-radius: 4px; }
.chat-bubble ul, .chat-bubble ol { margin: 4px 0; padding-left: 20px; }
.chat-role { font-size: 10.5px; color: var(--text-faint); margin: 0 4px 3px; letter-spacing: 0.04em; }
.chat-msg.assistant .chat-bubble.thinking { color: var(--text-dim); font-style: italic; }
.chat-input-wrap { display: flex; gap: 8px; align-items: flex-end; padding: 12px; border-top: 1px solid var(--border); background: var(--bg-2); }
.chat-input { flex: 1; resize: none; max-height: 160px; background: var(--bg-3); color: var(--text); border: 1px solid var(--border); border-radius: 8px; padding: 9px 12px; font-size: 13.5px; font-family: var(--font-ui); line-height: 1.5; }
.chat-input:focus { outline: none; border-color: var(--accent); }
.chat-foot { padding: 4px 14px 8px; background: var(--bg-2); }
.chat-cwd { font-size: 10.5px; color: var(--text-faint); font-family: var(--font-mono); }

// ---------- AI 对话窗：统一聊天 UI，后端切 cursor / api / codex（走 /api/chat SSE）----------
const chat = {
  backend: 'cursor',
  sessionId: '',   // cursor：会话 id，用于 --resume 多轮
  history: [],     // api：[{role,content}] 多轮上下文
  streaming: false,
  cfg: { chatApiBaseUrl: '', chatApiModel: '', hasApiKey: false },
  async open() {
    $('#chat-overlay').classList.remove('hidden');
    await this.loadCfg();
    if (!$('#chat-messages').children.length) this.renderEmpty();
    this.updateCwd();
    setTimeout(() => $('#chat-input').focus(), 50);
  },
  close() { $('#chat-overlay').classList.add('hidden'); },
  toggle() { $('#chat-overlay').classList.contains('hidden') ? this.open() : this.close(); },
  backendLabel() { return this.backend === 'api' ? 'API' : this.backend === 'codex' ? 'Codex' : 'Cursor'; },
  updateCwd() { $('#chat-cwd').textContent = '工作目录：' + (state.cwd || state.home || ''); },
  renderEmpty() {
    $('#chat-messages').innerHTML = `<div class="chat-empty">和 AI 对话，让它在当前目录里干活<br><span style="font-size:11.5px">当前后端 <b>${this.backendLabel()}</b>，右上角可切换</span></div>`;
  },
  async loadCfg() {
    try {
      this.cfg = await (await fetch('/api/chat-config')).json();
      this.backend = this.cfg.chatBackend || 'cursor';
      $('#chat-backend').value = this.backend;
      $('#chat-api-url').value = this.cfg.chatApiBaseUrl || '';
      $('#chat-api-model').value = this.cfg.chatApiModel || '';
      this.refreshStatus();
    } catch { /* */ }
  },
  refreshStatus() {
    const s = $('#chat-status'); if (!s) return;
    if (this.backend === 'api') s.textContent = this.cfg.hasApiKey ? (this.cfg.chatApiModel || 'API 已配置') : '未配置 API（点 ⚙）';
    else if (this.backend === 'codex') s.textContent = '未安装 codex CLI';
    else s.textContent = 'Cursor Agent';
  },
  async setBackend(b) {
    this.backend = b; this.refreshStatus();
    if (!$('#chat-messages').querySelector('.chat-msg')) this.renderEmpty();
    try { await fetch('/api/chat-config', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ chatBackend: b }) }); } catch { /* */ }
  },
  newChat() { this.sessionId = ''; this.history = []; $('#chat-messages').innerHTML = ''; this.renderEmpty(); },
  async saveApi() {
    const body = { chatApiBaseUrl: $('#chat-api-url').value, chatApiModel: $('#chat-api-model').value };
    const key = $('#chat-api-key').value; if (key) body.chatApiKey = key;
    try {
      this.cfg = await (await fetch('/api/chat-config', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) })).json();
      $('#chat-api-key').value = ''; this.refreshStatus(); toast('已保存 API 设置'); $('#chat-settings-panel').classList.add('hidden');
    } catch { toast('保存失败', true); }
  },
  md(t) { return (!window.__noMarked && window.marked) ? window.marked.parse(t) : this.esc(t).replace(/\n/g, '<br>'); },
  esc(s) { return String(s).replace(/[&<>]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c])); },
  scroll() { const m = $('#chat-messages'); m.scrollTop = m.scrollHeight; },
  addBubble(role, text) {
    const empty = $('#chat-messages .chat-empty'); if (empty) empty.remove();
    const wrap = document.createElement('div'); wrap.className = 'chat-msg ' + role;
    const r = document.createElement('div'); r.className = 'chat-role'; r.textContent = role === 'user' ? '你' : this.backendLabel();
    const b = document.createElement('div'); b.className = 'chat-bubble';
    if (role === 'user') b.textContent = text; else b.innerHTML = this.md(text || '');
    wrap.appendChild(r); wrap.appendChild(b); $('#chat-messages').appendChild(wrap); this.scroll();
    return b;
  },
  parseSSE(chunk) {
    let event = 'message', data = '';
    for (const line of chunk.split('\n')) {
      if (line.startsWith('event:')) event = line.slice(6).trim();
      else if (line.startsWith('data:')) data += line.slice(5).trim();
    }
    if (!data) return null;
    try { return { event, data: JSON.parse(data) }; } catch { return { event, data: {} }; }
  },
  autosize(ta) { ta.style.height = 'auto'; ta.style.height = Math.min(160, ta.scrollHeight) + 'px'; },
  async send() {
    if (this.streaming) return;
    const ta = $('#chat-input'); const msg = ta.value.trim(); if (!msg) return;
    ta.value = ''; this.autosize(ta);
    this.addBubble('user', msg);
    if (this.backend === 'api') this.history.push({ role: 'user', content: msg });
    const bubble = this.addBubble('assistant', ''); bubble.classList.add('thinking'); bubble.textContent = '思考中…';
    this.streaming = true; $('#chat-send').disabled = true;
    let acc = '', started = false;
    try {
      const res = await fetch('/api/chat', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ backend: this.backend, message: msg, sessionId: this.sessionId, cwd: state.cwd || state.home, history: this.backend === 'api' ? this.history.slice(0, -1) : undefined }),
      });
      const reader = res.body.getReader(); const dec = new TextDecoder(); let buf = '';
      for (;;) {
        const { done, value } = await reader.read(); if (done) break;
        buf += dec.decode(value, { stream: true });
        let idx;
        while ((idx = buf.indexOf('\n\n')) >= 0) {
          const ev = this.parseSSE(buf.slice(0, idx)); buf = buf.slice(idx + 2); if (!ev) continue;
          if (ev.event === 'session') this.sessionId = ev.data.id || this.sessionId;
          else if (ev.event === 'delta') { if (!started) { started = true; bubble.classList.remove('thinking'); bubble.textContent = ''; } acc += ev.data.text || ''; bubble.innerHTML = this.md(acc); this.scroll(); }
          else if (ev.event === 'result') { if (ev.data.text && !acc) { acc = ev.data.text; bubble.classList.remove('thinking'); bubble.innerHTML = this.md(acc); } }
          else if (ev.event === 'error') { bubble.classList.remove('thinking'); bubble.innerHTML = `<span style="color:var(--accent)">⚠ ${this.esc(ev.data.message || '出错了')}</span>`; }
        }
      }
      if (!started && !acc && bubble.textContent === '思考中…') { bubble.classList.remove('thinking'); bubble.textContent = '（无回复）'; }
    } catch (e) { bubble.classList.remove('thinking'); bubble.innerHTML = `<span style="color:var(--accent)">⚠ ${this.esc(e.message)}</span>`; }
    finally { this.streaming = false; $('#chat-send').disabled = false; if (this.backend === 'api' && acc) this.history.push({ role: 'assistant', content: acc }); this.scroll(); }
  },
};

// ---------- 内嵌终端（仅桌面 app；浏览器版优雅降级）----------

$('#term-cursor').onclick = () => term.launchAgent('cursor-agent');
$('#btn-chat').onclick = () => chat.open();
$('#chat-close').onclick = () => chat.close();
$('#chat-new').onclick = () => chat.newChat();
$('#chat-settings').onclick = () => $('#chat-settings-panel').classList.toggle('hidden');
$('#chat-api-save').onclick = () => chat.saveApi();
$('#chat-backend').onchange = (e) => chat.setBackend(e.target.value);
$('#chat-send').onclick = () => chat.send();
$('#chat-input').addEventListener('input', (e) => chat.autosize(e.target));
$('#chat-input').addEventListener('keydown', (e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); chat.send(); } });
$('#chat-overlay').addEventListener('click', (e) => { if (e.target.id === 'chat-overlay') chat.close(); });

