/* ---------- AI 对话窗（嵌入式停靠面板，对称 #terminal-panel） ---------- */
#chat-panel { flex: 0 0 auto; display: flex; flex-direction: column; background: var(--panel); min-height: 0; min-width: 0; }
#chat-panel.hidden { display: none; }
.dock-bottom #chat-panel { width: 100%; border-top: 1px solid var(--border); }
.dock-right #chat-panel { height: 100%; border-left: 1px solid var(--border); }
/* 终端/对话 标签切换 */
.side-tabs { display: flex; gap: 2px; flex: 0 0 auto; background: var(--bg-3); border-radius: 7px; padding: 2px; }
.side-tab { background: transparent; border: none; color: var(--text-dim); font-size: 12px; padding: 3px 11px; border-radius: 5px; cursor: pointer; transition: 0.12s; }
.side-tab:hover { color: var(--text); }
.side-tab.active { background: var(--accent); color: var(--accent-ink); font-weight: 600; }
#chat-panel .chat-head-right { display: flex; align-items: center; gap: 6px; }
.chat-select { background: var(--bg-3); color: var(--text); border: 1px solid var(--border); border-radius: 6px; padding: 4px 8px; font-size: 12.5px; cursor: pointer; }
.chat-status { font-size: 11.5px; color: var(--text-dim); padding: 5px 12px 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; flex: 0 0 auto; }
.chat-status:empty { display: none; }
.chat-iconbtn { background: transparent; border: 1px solid transparent; color: var(--text-dim); border-radius: 6px; padding: 4px 8px; font-size: 13px; cursor: pointer; transition: 0.12s; }
.chat-iconbtn:hover { background: var(--bg-3); color: var(--text); }

.chat-foot { padding: 4px 14px 8px; background: var(--bg-2); }
.chat-cwd { font-size: 10.5px; color: var(--text-faint); font-family: var(--font-mono); }
.chat-prov-select { flex: 1; background: var(--bg-3); color: var(--text); border: 1px solid var(--border); border-radius: 6px; padding: 6px 9px; font-size: 12.5px; cursor: pointer; }
.chat-attach-btn { flex: 0 0 auto; width: 36px; height: 36px; border-radius: 8px; background: var(--bg-3); color: var(--text-dim); border: 1px solid var(--border); font-size: 19px; line-height: 1; cursor: pointer; transition: 0.12s; }
.chat-attach-btn:hover { color: var(--accent); border-color: var(--accent); }
.chat-attachments { display: flex; flex-wrap: wrap; gap: 8px; padding: 8px 12px 0; flex: 0 0 auto; }
.chat-attachments.hidden { display: none; }
.chat-chip { display: flex; align-items: center; gap: 6px; background: var(--bg-3); border: 1px solid var(--border); border-radius: 8px; padding: 4px 6px 4px 8px; font-size: 11.5px; color: var(--text); max-width: 220px; }
.chat-chip img { width: 28px; height: 28px; object-fit: cover; border-radius: 4px; flex: 0 0 auto; }
.chat-chip .chip-name { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.chat-chip .chip-x { cursor: pointer; color: var(--text-faint); padding: 0 2px; font-size: 13px; }
.chat-chip .chip-x:hover { color: var(--accent); }
.chat-bubble .chat-img { max-width: 220px; border-radius: 8px; margin: 4px 0; display: block; }
.chat-bubble .chat-att-note { font-size: 11px; color: var(--text-faint); }
#chat-panel.chat-drop::after { content: '松开 · 加入对话'; position: absolute; inset: 6px; z-index: 20; display: flex; align-items: center; justify-content: center; pointer-events: none; border: 2px dashed var(--accent); border-radius: var(--radius); background: var(--accent-soft); color: var(--accent); font-size: 13px; font-weight: 600; }
#chat-panel.chat-drop { position: relative; }

