const chat = {
  backend: 'cursor',
  sessionId: '',   // cursor：会话 id，用于 --resume 多轮
  history: [],     // api：[{role,content}] 多轮上下文
  streaming: false,
  cfg: { chatApiBaseUrl: '', chatApiModel: '', hasApiKey: false },
  async open() {
    $('#chat-overlay').classList.remove('hidden');
    await this.loadCfg();
    if (!$('#chat-messages').children.length) this.renderEmpty();
    this.updateCwd();
    setTimeout(() => $('#chat-input').focus(), 50);
  },
  close() { $('#chat-overlay').classList.add('hidden'); },
  toggle() { $('#chat-overlay').classList.contains('hidden') ? this.open() : this.close(); },
  backendLabel() { return this.backend === 'api' ? 'API' : this.backend === 'codex' ? 'Codex' : 'Cursor'; },
  updateCwd() { $('#chat-cwd').textContent = '工作目录：' + (state.cwd || state.home || ''); },
  renderEmpty() {
    $('#chat-messages').innerHTML = `<div class="chat-empty">和 AI 对话，让它在当前目录里干活<br><span style="font-size:11.5px">当前后端 <b>${this.backendLabel()}</b>，右上角可切换</span></div>`;
  },
  async loadCfg() {
    try {
      this.cfg = await (await fetch('/api/chat-config')).json();
      this.backend = this.cfg.chatBackend || 'cursor';
      $('#chat-backend').value = this.backend;
      $('#chat-api-url').value = this.cfg.chatApiBaseUrl || '';
      $('#chat-api-model').value = this.cfg.chatApiModel || '';
      this.refreshStatus();
    } catch { /* */ }
  },
  refreshStatus() {
    const s = $('#chat-status'); if (!s) return;
    if (this.backend === 'api') s.textContent = this.cfg.hasApiKey ? (this.cfg.chatApiModel || 'API 已配置') : '未配置 API（点 ⚙）';
    else if (this.backend === 'codex') s.textContent = '未安装 codex CLI';
    else s.textContent = 'Cursor Agent';
  },
  async setBackend(b) {
    this.backend = b; this.refreshStatus();
    if (!$('#chat-messages').querySelector('.chat-msg')) this.renderEmpty();
    try { await fetch('/api/chat-config', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ chatBackend: b }) }); } catch { /* */ }
  },
  newChat() { this.sessionId = ''; this.history = []; $('#chat-messages').innerHTML = ''; this.renderEmpty(); },
  async saveApi() {
    const body = { chatApiBaseUrl: $('#chat-api-url').value, chatApiModel: $('#chat-api-model').value };
    const key = $('#chat-api-key').value; if (key) body.chatApiKey = key;
    try {
      this.cfg = await (await fetch('/api/chat-config', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) })).json();
      $('#chat-api-key').value = ''; this.refreshStatus(); toast('已保存 API 设置'); $('#chat-settings-panel').classList.add('hidden');
    } catch { toast('保存失败', true); }
  },
  md(t) { return (!window.__noMarked && window.marked) ? window.marked.parse(t) : this.esc(t).replace(/\n/g, '<br>'); },
  esc(s) { return String(s).replace(/[&<>]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c])); },
  scroll() { const m = $('#chat-messages'); m.scrollTop = m.scrollHeight; },
  addBubble(role, text) {
    const empty = $('#chat-messages .chat-empty'); if (empty) empty.remove();
    const wrap = document.createElement('div'); wrap.className = 'chat-msg ' + role;
    const r = document.createElement('div'); r.className = 'chat-role'; r.textContent = role === 'user' ? '你' : this.backendLabel();
    const b = document.createElement('div'); b.className = 'chat-bubble';
    if (role === 'user') b.textContent = text; else b.innerHTML = this.md(text || '');
    wrap.appendChild(r); wrap.appendChild(b); $('#chat-messages').appendChild(wrap); this.scroll();
    return b;
  },
  parseSSE(chunk) {
    let event = 'message', data = '';
    for (const line of chunk.split('\n')) {
      if (line.startsWith('event:')) event = line.slice(6).trim();
      else if (line.startsWith('data:')) data += line.slice(5).trim();
    }
    if (!data) return null;
    try { return { event, data: JSON.parse(data) }; } catch { return { event, data: {} }; }
  },
  autosize(ta) { ta.style.height = 'auto'; ta.style.height = Math.min(160, ta.scrollHeight) + 'px'; },
  async send() {
    if (this.streaming) return;
    const ta = $('#chat-input'); const msg = ta.value.trim(); if (!msg) return;
    ta.value = ''; this.autosize(ta);
    this.addBubble('user', msg);
    if (this.backend === 'api') this.history.push({ role: 'user', content: msg });
    const bubble = this.addBubble('assistant', ''); bubble.classList.add('thinking'); bubble.textContent = '思考中…';
    this.streaming = true; $('#chat-send').disabled = true;
    let acc = '', started = false;
    try {
      const res = await fetch('/api/chat', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ backend: this.backend, message: msg, sessionId: this.sessionId, cwd: state.cwd || state.home, history: this.backend === 'api' ? this.history.slice(0, -1) : undefined }),
      });
      const reader = res.body.getReader(); const dec = new TextDecoder(); let buf = '';
      for (;;) {
        const { done, value } = await reader.read(); if (done) break;
        buf += dec.decode(value, { stream: true });
        let idx;
        while ((idx = buf.indexOf('\n\n')) >= 0) {
          const ev = this.parseSSE(buf.slice(0, idx)); buf = buf.slice(idx + 2); if (!ev) continue;
          if (ev.event === 'session') this.sessionId = ev.data.id || this.sessionId;
          else if (ev.event === 'delta') { if (!started) { started = true; bubble.classList.remove('thinking'); bubble.textContent = ''; } acc += ev.data.text || ''; bubble.innerHTML = this.md(acc); this.scroll(); }
          else if (ev.event === 'result') { if (ev.data.text && !acc) { acc = ev.data.text; bubble.classList.remove('thinking'); bubble.innerHTML = this.md(acc); } }
          else if (ev.event === 'error') { bubble.classList.remove('thinking'); bubble.innerHTML = `<span style="color:var(--accent)">⚠ ${this.esc(ev.data.message || '出错了')}</span>`; }
        }
      }
      if (!started && !acc && bubble.textContent === '思考中…') { bubble.classList.remove('thinking'); bubble.textContent = '（无回复）'; }
    } catch (e) { bubble.classList.remove('thinking'); bubble.innerHTML = `<span style="color:var(--accent)">⚠ ${this.esc(e.message)}</span>`; }
    finally { this.streaming = false; $('#chat-send').disabled = false; if (this.backend === 'api' && acc) this.history.push({ role: 'assistant', content: acc }); this.scroll(); }
  },
};

