const chat = {
  backend: 'cursor',
  sessionId: '',   // cursor：会话 id，用于 --resume 多轮
  history: [],     // api：[{role,content}] 多轮上下文
  streaming: false,
  attachments: [], // {path,name,mime,isImage,thumbUrl}
  cfg: { chatApiBaseUrl: '', chatApiModel: '', chatApiProvider: '', hasApiKey: false },
  _provInit: false,

  isOpen() { return !$('#chat-panel').classList.contains('hidden'); },
  toggleOpen() { this.isOpen() ? this.close() : this.open(); },
  async open() {
    const mb = $('#main-body');
    if (term.maximized) term.toggleMax(false);
    mb.classList.remove('fm-squeezed', 'term-max');
    mb.classList.toggle('dock-bottom', term.dock === 'bottom');
    mb.classList.toggle('dock-right', term.dock !== 'bottom');
    $('#terminal-panel').classList.add('hidden');
    $('#chat-panel').classList.remove('hidden');
    $('#terminal-resizer').classList.remove('hidden');
    this.applySize();
    $('#btn-chat').classList.add('active');
    $('#btn-terminal').classList.remove('active');
    this.syncTabs(true);
    if (!this._provInit) this.initProviders();
    await this.loadCfg();
    if (!$('#chat-messages').children.length) this.renderEmpty();
    this.updateCwd();
    setTimeout(() => $('#chat-input').focus(), 50);
  },
  close() {
    $('#chat-panel').classList.add('hidden');
    $('#terminal-resizer').classList.add('hidden');
    $('#main-body').classList.remove('fm-squeezed');
    $('#btn-chat').classList.remove('active');
  },
  showTerminal() {
    if (!term.available()) { toast('内嵌终端不可用（网页版没有终端）', true); return; }
    $('#chat-panel').classList.add('hidden');
    $('#btn-chat').classList.remove('active');
    term.open();
    this.syncTabs(false);
  },
  syncTabs(isChat) {
    document.querySelectorAll('.side-tab-term').forEach((b) => b.classList.toggle('active', !isChat));
    document.querySelectorAll('.side-tab-chat').forEach((b) => b.classList.toggle('active', isChat));
  },
  applySize() {
    const mb = $('#main-body'); const panel = $('#chat-panel'); const mbr = mb.getBoundingClientRect();
    if (term.dock === 'bottom') {
      const h = Number(localStorage.getItem('fb_term_h')) || (mbr.height ? Math.round(mbr.height * 2 / 3) : 300);
      panel.style.height = h + 'px'; panel.style.width = '';
    } else {
      const w = Number(localStorage.getItem('fb_term_w')) || (mbr.width ? Math.round(mbr.width * 2 / 3) : 460);
      panel.style.width = w + 'px'; panel.style.height = '';
    }
  },
  backendLabel() { return this.backend === 'api' ? 'API' : this.backend === 'codex' ? 'Codex' : 'Cursor'; },
  updateCwd() { $('#chat-cwd').textContent = '工作目录：' + (state.cwd || state.home || ''); },
  renderEmpty() {
    $('#chat-messages').innerHTML = `<div class="chat-empty">和 AI 对话，让它在当前目录里干活<br><span style="font-size:11.5px">后端 <b>${this.backendLabel()}</b> · 左上角切 终端/对话 · 「＋」可传文件、图片</span></div>`;
  },
  initProviders() {
    const sel = $('#chat-provider'); if (!sel) return;
    sel.innerHTML = CHAT_PROVIDERS.map((p) => `<option value="${p.id}">${p.name}</option>`).join('');
    this._provInit = true;
  },
  applyProvider(id) {
    const p = CHAT_PROVIDERS.find((x) => x.id === id); if (!p) return;
    if (p.id !== 'custom') {
      $('#chat-api-url').value = p.url;
      $('#chat-model-list').innerHTML = p.models.map((m) => `<option value="${m}"></option>`).join('');
      $('#chat-api-model').value = p.models[0] || '';
    }
  },
  async loadCfg() {
    try {
      this.cfg = await (await fetch('/api/chat-config')).json();
      this.backend = this.cfg.chatBackend || 'cursor';
      $('#chat-backend').value = this.backend;
      $('#chat-api-url').value = this.cfg.chatApiBaseUrl || '';
      $('#chat-api-model').value = this.cfg.chatApiModel || '';
      if (this.cfg.chatApiProvider && $('#chat-provider')) {
        $('#chat-provider').value = this.cfg.chatApiProvider;
        const p = CHAT_PROVIDERS.find((x) => x.id === this.cfg.chatApiProvider);
        if (p && p.id !== 'custom') $('#chat-model-list').innerHTML = p.models.map((m) => `<option value="${m}"></option>`).join('');
      }
      this.refreshStatus();
    } catch { /* */ }
  },
  refreshStatus() {
    const s = $('#chat-status'); if (!s) return;
    if (this.backend === 'api') s.textContent = this.cfg.hasApiKey ? ('API · ' + (this.cfg.chatApiModel || '已配置')) : '未配置 API —— 点 ⚙ 选供应商、填 Key';
    else if (this.backend === 'codex') s.textContent = '未安装 codex CLI（先装才能用）';
    else s.textContent = 'Cursor Agent（你已登录）';
  },
  async setBackend(b) {
    this.backend = b; this.refreshStatus();
    if (!$('#chat-messages').querySelector('.chat-msg')) this.renderEmpty();
    if (b === 'api' && !this.cfg.hasApiKey) $('#chat-settings-panel').classList.remove('hidden'); // 没配过就展开设置
    try { await fetch('/api/chat-config', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ chatBackend: b }) }); } catch { /* */ }
  },
