const CURSOR_GROUP_ORDER = ['Anthropic', 'OpenAI', 'Google', 'xAI', 'Moonshot', 'Cursor', '其他'];
// 把显示名拆成「家族 + 强度变体」：剥掉结尾的强度词（Max 视为家族层级，不剥）
const CURSOR_VARIANT_WORDS = ['Extra High', 'High', 'Medium', 'Low', 'None', 'Thinking', 'Fast'];
function splitModelName(name) {
  let fam = String(name).trim();
  const variant = [];
  let changed = true;
  while (changed) {
    changed = false;
    for (const w of CURSOR_VARIANT_WORDS) {
      if (fam.toLowerCase().endsWith(' ' + w.toLowerCase())) {
        variant.unshift(w);
        fam = fam.slice(0, fam.length - w.length - 1).trim();
        changed = true;
        break;
      }
    }
  }
  return { family: fam || name, variant: variant.join(' ') || '标准' };
}

