async loadCursorModels() {
  if (this._modelsLoaded) return;
  const pop = $('#chat-model-pop'); if (!pop) return;
  try {
    let models = await (await fetch('/api/cursor-models')).json();
    if (!Array.isArray(models) || !models.length) return;
    models = models.filter((m) => !/fable/i.test(m.id) && !/NO ZDR/i.test(m.name || '')); // 删掉用不了的（Fable / NO ZDR）
    this._modelMap = {}; models.forEach((m) => { this._modelMap[m.id] = m.name; });
    const companies = {}; // 公司 → 家族 → [变体]
    for (const m of models) {
      if (m.id === 'auto') continue;
      const co = cursorModelGroup(m.id);
      const { family, variant } = splitModelName(m.name);
      companies[co] = companies[co] || {};
      (companies[co][family] = companies[co][family] || []).push({ id: m.id, variant });
    }
    let html = '<div class="cm-default" data-id="">模型：默认</div>';
    if (models.some((m) => m.id === 'auto')) html += '<div class="cm-default" data-id="auto">Auto（自动选）</div>';
    for (const co of CURSOR_GROUP_ORDER) {
      const fams = companies[co]; if (!fams) continue;
      html += `<div class="cm-company"><div class="cm-co-head"><span class="cm-tri">▸</span>${this.esc(co)}</div><div class="cm-co-body collapsed">`;
      for (const fam of Object.keys(fams)) {
        const vs = fams[fam];
        if (vs.length === 1) {
          html += `<div class="cm-leaf" data-id="${this.esc(vs[0].id)}">${this.esc(fam)}</div>`;
        } else {
          html += `<div class="cm-family"><div class="cm-fam-head"><span class="cm-tri">▸</span>${this.esc(fam)}</div><div class="cm-fam-body collapsed">`;
          for (const v of vs) html += `<div class="cm-leaf" data-id="${this.esc(v.id)}">${this.esc(v.variant)}</div>`;
          html += '</div></div>';
        }
      }
      html += '</div></div>';
    }
    pop.innerHTML = html;
    pop.querySelectorAll('.cm-co-head').forEach((h) => { h.onclick = () => { const body = h.nextElementSibling; body.classList.toggle('collapsed'); h.querySelector('.cm-tri').textContent = body.classList.contains('collapsed') ? '▸' : '▾'; }; });
    pop.querySelectorAll('.cm-fam-head').forEach((h) => { h.onclick = (e) => { e.stopPropagation(); const body = h.nextElementSibling; body.classList.toggle('collapsed'); h.querySelector('.cm-tri').textContent = body.classList.contains('collapsed') ? '▸' : '▾'; }; });
    pop.querySelectorAll('.cm-default, .cm-leaf').forEach((el) => { el.onclick = () => this.selectCursorModel(el.dataset.id); });
    this._modelsLoaded = true;
    this.updateModelLabel();
  } catch { /* */ }
},
selectCursorModel(id) {
  this.cursorModel = id || '';
  this._saveCfg({ chatCursorModel: this.cursorModel });
  this.updateModelLabel(); this.markModelSel(); this.refreshStatus();
  $('#chat-model-pop').classList.add('hidden');
},
modelLabel(id) {
  if (!id) return '模型：默认';
  if (id === 'auto') return 'Auto（自动选）';
  return (this._modelMap && this._modelMap[id]) || id;
},
updateModelLabel() { const l = $('#chat-model-label'); if (l) l.textContent = this.modelLabel(this.cursorModel); },
markModelSel() {
  const pop = $('#chat-model-pop'); if (!pop) return;
  pop.querySelectorAll('.cm-default, .cm-leaf').forEach((el) => el.classList.toggle('sel', (el.dataset.id || '') === (this.cursorModel || '')));
  const sel = pop.querySelector('.cm-leaf.sel');
  if (sel) { let p = sel.parentElement; while (p && p !== pop) { if (p.classList.contains('cm-co-body') || p.classList.contains('cm-fam-body')) { p.classList.remove('collapsed'); const head = p.previousElementSibling; const t = head && head.querySelector('.cm-tri'); if (t) t.textContent = '▾'; } p = p.parentElement; } }
},
toggleModelPop() { const pop = $('#chat-model-pop'); if (!pop) return; pop.classList.toggle('hidden'); if (!pop.classList.contains('hidden')) this.markModelSel(); },

