const ORDER = ['Anthropic', 'OpenAI', 'Google', 'xAI', 'Moonshot', 'Cursor', '其他'];
const VW = ['Extra High', 'High', 'Medium', 'Low', 'None', 'Thinking', 'Fast'];
function group(id) {
  if (id.startsWith('composer')) return 'Cursor';
  if (id.startsWith('claude')) return 'Anthropic';
  if (id.startsWith('gemini')) return 'Google';
  if (id.startsWith('grok')) return 'xAI';
  if (id.startsWith('kimi')) return 'Moonshot';
  if (id.startsWith('gpt') || id.includes('codex')) return 'OpenAI';
  return '其他';
}
function split(name) {
  let fam = name.trim(); const v = []; let ch = true;
  while (ch) { ch = false; for (const w of VW) { if (fam.toLowerCase().endsWith(' ' + w.toLowerCase())) { v.unshift(w); fam = fam.slice(0, fam.length - w.length - 1).trim(); ch = true; break; } } }
  return { family: fam || name, variant: v.join(' ') || '标准' };
}
const res = await fetch('http://localhost:4567/api/cursor-models');
let models = await res.json();
const total = models.length;
models = models.filter((m) => !/fable/i.test(m.id) && !/NO ZDR/i.test(m.name || ''));
console.log('总数', total, '过滤Fable后', models.length, 'Fable剩余', models.filter(m=>/fable/i.test(m.id)).length);
const co = {};
for (const m of models) { if (m.id === 'auto') continue; const g = group(m.id); const { family, variant } = split(m.name); co[g] = co[g] || {}; (co[g][family] = co[g][family] || []).push(variant); }
for (const c of ORDER) { if (!co[c]) continue; const fams = Object.keys(co[c]); console.log('\n== ' + c + ' == (' + fams.length + ' 个模型家族)'); for (const f of fams) console.log('   ' + f + '  [' + co[c][f].join(', ') + ']'); }

